import json, urllib.request, websocket, time, sys, threading

def new_tab():
    req = urllib.request.Request("http://127.0.0.1:9222/json/new?about:blank", method="PUT")
    with urllib.request.urlopen(req) as r:
        return json.loads(r.read().decode())["webSocketDebuggerUrl"]

ws = websocket.create_connection(new_tab(), timeout=60, origin="http://127.0.0.1:9222")
mid = 0
pending = {}
lock = threading.Lock()

def recv_loop():
    while True:
        try:
            msg = json.loads(ws.recv())
        except Exception:
            return
        if "id" in msg:
            with lock:
                pending[msg["id"]] = msg
        else:
            m = msg.get("method")
            if m == "Page.javascriptDialogOpening":
                with lock:
                    ws.send(json.dumps({"id": 9000, "method": "Page.handleJavaScriptDialog", "params": {"accept": True}}))
                print("DIALOG:", json.dumps(msg.get("params", {}))[:300])
            elif m.startswith("Network.") or m.startswith("Runtime.console"):
                print("EVENT:", m, json.dumps(msg.get("params", {}))[:300])

threading.Thread(target=recv_loop, daemon=True).start()

def send(method, params=None, timeout=20):
    global mid
    mid += 1
    with lock:
        ws.send(json.dumps({"id": mid, "method": method, "params": params or {}}))
    t0 = time.time()
    while time.time() - t0 < timeout:
        with lock:
            if mid in pending:
                return pending.pop(mid)
        time.sleep(0.05)
    return {"error": "timeout"}

send("Page.enable")
send("Runtime.enable")
send("Network.enable")
url = sys.argv[1]
print("nav:", json.dumps(send("Page.navigate", {"url": url}))[:200])
time.sleep(6)
for expr in ["document.body.innerHTML", "document.cookie", "location.href", "localStorage.length", "performance.getEntriesByType('resource').map(e=>e.name).join('|')"]:
    r = send("Runtime.evaluate", {"expression": expr, "returnByValue": True})
    print("EXPR", expr, "=>", json.dumps(r.get("result", {}).get("result", {}))[:400])
EOF
